"use client";

import * as React from "react";
import { ChevronRightIcon } from "lucide-react";

import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { cn } from "@/lib/utils";

function Trace({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="trace"
      className={cn(
        "flex flex-col gap-1 text-sm",
        "*:has-[>[data-slot=trace-line]]:flex",
        "*:has-[>[data-slot=trace-line]]:w-fit",
        "*:has-[>[data-slot=trace-line]]:max-w-full",
        "*:has-[>[data-slot=trace-line]]:min-w-0",
        "*:has-[>[data-slot=trace-line]]:rounded-lg",
        "*:has-[>[data-slot=trace-line]]:text-left",
        "*:has-[>[data-slot=trace-line]]:outline-none",
        "*:has-[>[data-slot=trace-line]]:focus-visible:ring-3",
        "*:has-[>[data-slot=trace-line]]:focus-visible:ring-ring/30",
        className
      )}
      {...props}
    />
  );
}

function TraceLine({
  className,
  status,
  ...props
}: React.ComponentProps<"span"> & {
  status?: "running" | "error" | "pending";
}) {
  return (
    <span
      data-slot="trace-line"
      data-status={status}
      className={cn(
        "group/trace-line flex min-w-0 items-center gap-2 text-muted-foreground",
        status === "running" && "text-foreground",
        status === "error" && "text-destructive",
        status === "pending" && "opacity-60",
        className
      )}
      {...props}
    />
  );
}

function TraceIcon({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="trace-icon"
      aria-hidden
      className={cn(
        "flex size-4 shrink-0 items-center justify-center [&>svg]:size-3.5",
        className
      )}
      {...props}
    />
  );
}

function TraceTitle({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="trace-title"
      className={cn(
        "min-w-0 truncate",
        "group-data-[status=running]/trace-line:shimmer",
        className
      )}
      {...props}
    />
  );
}

function TraceDescription({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="trace-description"
      className={cn("ml-auto shrink-0 text-xs tabular-nums", className)}
      {...props}
    />
  );
}

function TraceCollapsible({
  className,
  ...props
}: React.ComponentProps<typeof Collapsible>) {
  return (
    <Collapsible
      data-slot="trace-collapsible"
      className={cn("group/trace-collapsible flex flex-col", className)}
      {...props}
    />
  );
}

function TraceCollapsibleTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof CollapsibleTrigger>) {
  return (
    <CollapsibleTrigger
      data-slot="trace-collapsible-trigger"
      className={cn(
        "flex w-full items-center gap-2 rounded-lg text-left outline-none focus-visible:ring-2 focus-visible:ring-ring",
        className
      )}
      {...props}
    >
      {children}
      <ChevronRightIcon className="ml-auto size-3.5 shrink-0 text-muted-foreground transition-transform duration-200 group-data-[state=open]/trace-collapsible:rotate-90" />
    </CollapsibleTrigger>
  );
}

function TraceCollapsibleContent({
  className,
  children,
  keepMounted = false,
  ...props
}: React.ComponentProps<typeof CollapsibleContent> & {
  keepMounted?: boolean;
}) {
  return (
    <CollapsibleContent
      data-slot="trace-collapsible-content"
      forceMount={keepMounted ? true : undefined}
      className={cn(
        "overflow-hidden",
        keepMounted && "data-[state=closed]:h-0",
        "data-[state=closed]:animate-collapsible-up data-[state=open]:animate-collapsible-down",
        className
      )}
      {...props}
    >
      <div className="mt-1 ml-2 border-l border-border pb-2 pl-4">
        {children}
      </div>
    </CollapsibleContent>
  );
}

export {
  Trace,
  TraceLine,
  TraceIcon,
  TraceTitle,
  TraceDescription,
  TraceCollapsible,
  TraceCollapsibleTrigger,
  TraceCollapsibleContent,
};
